import { createChart, removeChart } from '@/test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts.all';

function countSplitLines(chart: EChartsType): number {
    let count = 0;
    chart.getZr().storage.traverse(function (el: any) {
        if (el.anid && typeof el.anid === 'string' && el.anid.indexOf('line_') === 0 && !el.ignore) {
            count++;
        }
    });
    return count;
}

function makeChart(splitLine: Record<string, unknown>): EChartsType {
    const chart = createChart();
    chart.setOption({
        animation: false,
        xAxis: { type: 'category', data: ['a', 'b', 'c'] },
        yAxis: {
            type: 'value',
            min: 0,
            max: 10,
            interval: 2,
            splitLine: splitLine
        },
        series: [{ type: 'bar', data: [1, 2, 3] }]
    });
    return chart;
}

describe('splitLine.showMinLine/showMaxLine', function () {
    it('renders all split lines by default (options absent)', function () {
        const chart = makeChart({ show: true });
        // ticks at 0, 2, 4, 6, 8, 10
        expect(countSplitLines(chart)).toEqual(6);
        removeChart(chart);
    });

    it('showMinLine: false hides only the min boundary line', function () {
        const chart = makeChart({ show: true, showMinLine: false });
        expect(countSplitLines(chart)).toEqual(5);
        removeChart(chart);
    });

    it('showMaxLine: false hides only the max boundary line', function () {
        const chart = makeChart({ show: true, showMaxLine: false });
        expect(countSplitLines(chart)).toEqual(5);
        removeChart(chart);
    });

    it('both false hides both boundary lines', function () {
        const chart = makeChart({ show: true, showMinLine: false, showMaxLine: false });
        expect(countSplitLines(chart)).toEqual(4);
        removeChart(chart);
    });

    it('both true keeps all lines', function () {
        const chart = makeChart({ show: true, showMinLine: true, showMaxLine: true });
        expect(countSplitLines(chart)).toEqual(6);
        removeChart(chart);
    });
});

